#include <SPI.h>
#include <MFRC522.h>
#include <Servo.h>

// =====================================================
// MFRC522
// =====================================================

#define SS_PIN 10
#define RST_PIN 9

MFRC522 rfid(SS_PIN, RST_PIN);


// =====================================================
// ПИНЫ
// =====================================================

#define SERVO_PIN 6
#define BUZZER_PIN 7


// =====================================================
// СЕРВОПРИВОД
// =====================================================

Servo doorServo;

// Положение дверцы
#define DOOR_CLOSED_ANGLE 0
#define DOOR_OPEN_ANGLE   90

// Текущее состояние дверцы
// false = закрыта
// true  = открыта
bool doorOpen = false;

// Время между шагами сервопривода.
// При 90 шагах и 22 мс движение занимает примерно 2 секунды.
#define SERVO_STEP_DELAY 22


// =====================================================
// РАЗРЕШЁННАЯ RFID-КАРТА
// =====================================================

// Пример UID карты
// Здесь необходимо указать UID твоей карты

byte authorizedUID[] = {
  0x12,
  0x34,
  0x56,
  0x78
};

// Количество байт UID
byte authorizedUIDLength = 4;


// =====================================================
// SETUP
// =====================================================

void setup() {

  Serial.begin(9600);

  // Запускаем SPI
  SPI.begin();

  // Запускаем MFRC522
  rfid.PCD_Init();

  // Настраиваем динамик
  pinMode(BUZZER_PIN, OUTPUT);

  // Подключаем сервопривод
  doorServo.attach(SERVO_PIN);

  // При запуске считаем дверцу закрытой
  doorServo.write(DOOR_CLOSED_ANGLE);
  doorOpen = false;

  Serial.println("--------------------------------");
  Serial.println("RFID система доступа запущена");
  Serial.println("Приложите карту...");
  Serial.println("--------------------------------");
}


// =====================================================
// LOOP
// =====================================================

void loop() {

  // Проверяем наличие новой карты
  if (!rfid.PICC_IsNewCardPresent()) {
    return;
  }

  // Пытаемся считать карту
  if (!rfid.PICC_ReadCardSerial()) {
    return;
  }


  // ---------------------------------------------------
  // Вывод UID карты в Serial Monitor
  // ---------------------------------------------------

  Serial.print("UID карты: ");

  for (byte i = 0; i < rfid.uid.size; i++) {

    if (rfid.uid.uidByte[i] < 0x10) {
      Serial.print("0");
    }

    Serial.print(rfid.uid.uidByte[i], HEX);
    Serial.print(" ");
  }

  Serial.println();


  // ---------------------------------------------------
  // Проверяем UID
  // ---------------------------------------------------

  if (isAuthorized()) {

    Serial.println("ДОСТУП РАЗРЕШЕН");

    // Один писк
    successBeep();

    // Открываем или закрываем дверцу
    toggleDoor();

  }
  else {

    Serial.println("ДОСТУП ЗАПРЕЩЕН");

    // Два писка
    errorBeep();
  }


  // ---------------------------------------------------
  // Завершаем работу с картой
  // ---------------------------------------------------

  rfid.PICC_HaltA();
  rfid.PCD_StopCrypto1();

  // Небольшая задержка, чтобы карта
  // не считывалась несколько раз подряд
  delay(500);
}


// =====================================================
// ПРОВЕРКА RFID UID
// =====================================================

bool isAuthorized() {

  // Проверяем длину UID
  if (rfid.uid.size != authorizedUIDLength) {
    return false;
  }


  // Сравниваем каждый байт UID
  for (byte i = 0; i < authorizedUIDLength; i++) {

    if (rfid.uid.uidByte[i] != authorizedUID[i]) {
      return false;
    }
  }

  return true;
}


// =====================================================
// ОДИН ПИСК — ДОСТУП РАЗРЕШЁН
// =====================================================

void successBeep() {

  tone(BUZZER_PIN, 2000);

  delay(150);

  noTone(BUZZER_PIN);
}


// =====================================================
// ДВА ПИСКА — ДОСТУП ЗАПРЕЩЁН
// =====================================================

void errorBeep() {

  // Первый писк
  tone(BUZZER_PIN, 1000);

  delay(150);

  noTone(BUZZER_PIN);


  // Пауза 0,5 секунды
  delay(500);


  // Второй писк
  tone(BUZZER_PIN, 1000);

  delay(150);

  noTone(BUZZER_PIN);
}


// =====================================================
// ПЛАВНОЕ ДВИЖЕНИЕ СЕРВОПРИВОДА
// =====================================================

void moveServoSmoothly(int startAngle, int endAngle) {

  // Движение вперёд: 0° → 90°
  if (startAngle < endAngle) {

    for (int angle = startAngle; angle <= endAngle; angle++) {

      doorServo.write(angle);

      delay(SERVO_STEP_DELAY);
    }
  }


  // Движение назад: 90° → 0°
  else {

    for (int angle = startAngle; angle >= endAngle; angle--) {

      doorServo.write(angle);

      delay(SERVO_STEP_DELAY);
    }
  }
}


// =====================================================
// ОТКРЫТИЕ / ЗАКРЫТИЕ ДВЕРЦЫ
// =====================================================

void toggleDoor() {

  // ---------------------------------------------------
  // ЕСЛИ ДВЕРЦА ЗАКРЫТА
  // ---------------------------------------------------

  if (doorOpen == false) {

    Serial.println("Открываем дверцу...");
    Serial.println("Плавное движение: 0 -> 90 градусов");

    // Плавно открываем дверцу
    moveServoSmoothly(
      DOOR_CLOSED_ANGLE,
      DOOR_OPEN_ANGLE
    );

    // Запоминаем новое состояние
    doorOpen = true;

    Serial.println("Дверца открыта.");
  }


  // ---------------------------------------------------
  // ЕСЛИ ДВЕРЦА ОТКРЫТА
  // ---------------------------------------------------

  else {

    Serial.println("Закрываем дверцу...");
    Serial.println("Плавное движение: 90 -> 0 градусов");

    // Плавно закрываем дверцу
    moveServoSmoothly(
      DOOR_OPEN_ANGLE,
      DOOR_CLOSED_ANGLE
    );

    // Запоминаем новое состояние
    doorOpen = false;

    Serial.println("Дверца закрыта.");
  }
}
